13	public class DuplicateIdentityHandler {
14	
15	    public void handle(@Parameter DuplicateIdentityException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
18	                "An owner with the same identity already exists");
19	        detail.setProperty("errors", java.util.List.of("identityKey"));
20	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
21	    }
